mapper.select:
SELECT o.id FROM ecom_order o
AND o.local_status = 'EXCEPTION' AND o.est_profit < 0
ORDER BY o.id DESC LIMIT #{limit}

SELECT r.id AS "id", r.store_id AS "storeId", s.name AS "storeName", s.platform AS "platform", s.marketplace AS "site", r.rating AS "rating", r.seller_sku AS "sku", r.platform_item_id AS "itemId", r.listing_id AS "listingId", r.title AS "title", r.content AS "content", r.reviewer AS "reviewer", r.review_date AS "reviewDate", r.order_id AS "orderId", r.platform_order_no AS "orderNo", r.replied AS "replied", l.material_id AS "materialId" FROM ecom_review r JOIN ecom_store s ON s.id = r.store_id LEFT JOIN ecom_listing l ON l.id = r.listing_id
AND r.id IN #{id}
AND r.rating <= #{maxRating}
ORDER BY r.id DESC LIMIT #{limit}

SELECT a.id AS "id", a.monitor_id AS "monitorId", a.alert_type AS "alertType", a.alert_date AS "alertDate", a.old_value AS "oldValue", a.new_value AS "newValue", m.monitor_type AS "monitorType", m.platform AS "monitorPlatform", m.marketplace AS "marketplace", m.item_id AS "itemId", m.title AS "title", m.seller_sku AS "sku", m.listing_id AS "listingId", m.store_id AS "storeId", m.seller_count AS "sellerCount", m.rank_main AS "rankMain", m.rating AS "rating", m.price AS "price", m.brand AS "brand", m.notify_user_id AS "notifyUserId", s.name AS "storeName", s.platform AS "platform", s.marketplace AS "site", l.material_id AS "materialId" FROM ecom_monitor_alert a JOIN ecom_monitor m ON m.id = a.monitor_id LEFT JOIN ecom_store s ON s.id = m.store_id LEFT JOIN ecom_listing l ON l.id = m.listing_id
AND a.id IN #{id}
AND a.alert_type IN #{t}
ORDER BY a.id DESC LIMIT #{limit}

SELECT g.id AS "id", g.store_id AS "storeId", g.sync_type AS "syncType", g.trigger_by AS "triggerBy", g.message AS "message", g.start_time AS "startTime", s.name AS "storeName", s.platform AS "platform", s.marketplace AS "site", s.code AS "storeCode" FROM ecom_sync_log g JOIN ecom_store s ON s.id = g.store_id WHERE g.success = 0
AND g.id = #{id} AND g.sync_type = 'AUTH' AND g.sync_type <> 'AUTH'
ORDER BY g.id DESC LIMIT #{limit}

SELECT i.id AS "id", i.doc_no AS "docNo", i.shipment_id AS "shipmentId", i.store_id AS "storeId", s.name AS "storeName", s.platform AS "platform", s.marketplace AS "site", i.status AS "status", i.carrier AS "carrier", i.tracking_no AS "trackingNo", i.ship_date AS "shipDate", i.eta_date AS "etaDate", i.receive_date AS "receiveDate", i.total_qty AS "totalQty", i.box_count AS "boxCount", w.name AS "toWarehouse" FROM ecom_inbound i LEFT JOIN ecom_store s ON s.id = i.store_id LEFT JOIN wms_warehouse w ON w.id = i.to_warehouse_id
AND i.id IN #{id}
AND i.status = 'SHIPPED' AND i.eta_date < #{overdueBefore} AND i.status = 'RECEIVED'
ORDER BY i.id DESC LIMIT #{limit}
